template:
% 视觉归一化：把最长边（含自动闭合的 DA）缩放到 6 个坐标单位（默认 1 单位 = 1cm，即最长边恒约 6cm；参数声明区由系统按参数值自动生成）；
% 只缩放坐标，线宽、字体、虚线样式保持不变；直角记号等装饰尺寸已除以 figscale 补偿，不随归一化缩小。
% DA 长度先由参数算出（A(0,0)、C、D 坐标代入两点距离公式），供 figscale 使用
\pgfmathsetmacro{\adlen}{sqrt((\ab - \bc*cos(\angleb) + \cd*cos(\angleb+\anglec))^2 + (\bc*sin(\angleb) - \cd*sin(\angleb+\anglec))^2)}
\pgfmathsetmacro{\figscale}{6 / max(\ab, \bc, \cd, \adlen)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % 四个顶点：A、B 在底边，C 由 bc 与∠B 定，D 由 cd 与∠C 定，DA 自动闭合（顶点逆时针）
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \pgfmathsetmacro{\Cx}{\ab - \bc*cos(\angleb)}
  \pgfmathsetmacro{\Cy}{\bc*sin(\angleb)}
  \coordinate (C) at (\Cx,\Cy);
  \pgfmathsetmacro{\Dx}{\Cx + \cd*cos(\angleb+\anglec)}
  \pgfmathsetmacro{\Dy}{\Cy - \cd*sin(\angleb+\anglec)}
  \coordinate (D) at (\Dx,\Dy);
  % 闭合边 DA 长度（归一化与直角记号用）
  \pgfmathsetmacro{\adlen}{sqrt(\Dx*\Dx + \Dy*\Dy)}
  % 四边中点：E=AB中点, F=BC中点, G=CD中点, H=DA中点
  \coordinate (E) at (\ab/2,0);
  \pgfmathsetmacro{\Fx}{(\ab + \Cx)/2}
  \pgfmathsetmacro{\Fy}{\Cy/2}
  \coordinate (F) at (\Fx,\Fy);
  \pgfmathsetmacro{\Gx}{(\Cx + \Dx)/2}
  \pgfmathsetmacro{\Gy}{(\Cy + \Dy)/2}
  \coordinate (G) at (\Gx,\Gy);
  \coordinate (H) at (\Dx/2,\Dy/2);
  % 四边形四边
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % ∠A 直角记号（A 在(0,0)，沿 AB、AD 两边方向）
  \ifnum\rightmarka>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \ab*0.2, \adlen*0.2)}
    \pgfmathsetmacro{\rmavx}{\Dx/\adlen}
    \pgfmathsetmacro{\rmavy}{\Dy/\adlen}
    \draw[thick] (\rmsz,0) -- (\rmsz+\rmsz*\rmavx,\rmsz*\rmavy) -- (\rmsz*\rmavx,\rmsz*\rmavy);
  \fi
  % ∠B 直角记号（B 在(\ab,0)，沿 BA、BC 两边方向）
  \ifnum\rightmarkb>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \ab*0.2, \bc*0.2)}
    \pgfmathsetmacro{\rmbux}{(\Cx-\ab)/\bc}
    \pgfmathsetmacro{\rmbuy}{\Cy/\bc}
    \draw[thick] (\ab-\rmsz,0) -- (\ab-\rmsz+\rmsz*\rmbux,\rmsz*\rmbuy) -- (\ab+\rmsz*\rmbux,\rmsz*\rmbuy);
  \fi
  % ∠C 直角记号（C 在(\Cx,\Cy)，沿 CB、CD 两边方向）
  \ifnum\rightmarkc>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \bc*0.2, \cd*0.2)}
    \pgfmathsetmacro{\rmcux}{(\ab-\Cx)/\bc}
    \pgfmathsetmacro{\rmcuy}{-\Cy/\bc}
    \pgfmathsetmacro{\rmcvx}{(\Dx-\Cx)/\cd}
    \pgfmathsetmacro{\rmcvy}{(\Dy-\Cy)/\cd}
    \draw[thick] (\Cx+\rmsz*\rmcux,\Cy+\rmsz*\rmcuy) -- (\Cx+\rmsz*\rmcux+\rmsz*\rmcvx,\Cy+\rmsz*\rmcuy+\rmsz*\rmcvy) -- (\Cx+\rmsz*\rmcvx,\Cy+\rmsz*\rmcvy);
  \fi
  % ∠D 直角记号（D 在(\Dx,\Dy)，沿 DC、DA 两边方向）
  \ifnum\rightmarkd>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \cd*0.2, \adlen*0.2)}
    \pgfmathsetmacro{\rmdux}{(\Cx-\Dx)/\cd}
    \pgfmathsetmacro{\rmduy}{(\Cy-\Dy)/\cd}
    \pgfmathsetmacro{\rmdvx}{-\Dx/\adlen}
    \pgfmathsetmacro{\rmdvy}{-\Dy/\adlen}
    \draw[thick] (\Dx+\rmsz*\rmdux,\Dy+\rmsz*\rmduy) -- (\Dx+\rmsz*\rmdux+\rmsz*\rmdvx,\Dy+\rmsz*\rmduy+\rmsz*\rmdvy) -- (\Dx+\rmsz*\rmdvx,\Dy+\rmsz*\rmdvy);
  \fi
  % 对角线（实线）
  \ifnum\showdiagac>0
    \draw[thick] (A) -- (C);
  \fi
  \ifnum\showdiagbd>0
    \draw[thick] (B) -- (D);
  \fi
  % 对角线交点：两线同开时画小圆点并标 O（绝对半径，不随坐标缩放；标签沿两对角线较宽夹角的角平分线偏移以避开两条线，偏移量做 figscale 补偿）
  \ifnum\showdiagac>0
    \ifnum\showdiagbd>0
      \pgfmathsetmacro{\tq}{\ab*\Dy/(\Cx*\Dy-\Cy*\Dx+\Cy*\ab)}
      \pgfmathsetmacro{\Ox}{\tq*\Cx}
      \pgfmathsetmacro{\Oy}{\tq*\Cy}
      \fill (\Ox,\Oy) circle [radius=1.6pt];
      \pgfmathsetmacro{\uax}{\Cx/sqrt(\Cx*\Cx+\Cy*\Cy)}
      \pgfmathsetmacro{\uay}{\Cy/sqrt(\Cx*\Cx+\Cy*\Cy)}
      \pgfmathsetmacro{\ubx}{(\Dx-\ab)/sqrt((\Dx-\ab)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\uby}{\Dy/sqrt((\Dx-\ab)^2+\Dy*\Dy)}
      \pgfmathsetmacro{\pax}{\uax+\ubx}
      \pgfmathsetmacro{\pay}{\uay+\uby}
      \pgfmathsetmacro{\pbx}{\uax-\ubx}
      \pgfmathsetmacro{\pby}{\uay-\uby}
      \pgfmathsetmacro{\pal}{sqrt(\pax*\pax+\pay*\pay)}
      \pgfmathsetmacro{\pbl}{sqrt(\pbx*\pbx+\pby*\pby)}
      \ifdim\pal pt<\pbl pt
        \pgfmathsetmacro{\wx}{\pax/\pal}
        \pgfmathsetmacro{\wy}{\pay/\pal}
      \else
        \pgfmathsetmacro{\wx}{\pbx/\pbl}
        \pgfmathsetmacro{\wy}{\pby/\pbl}
      \fi
      \ifdim\wy pt<0 pt
        \pgfmathsetmacro{\wx}{-\wx}
        \pgfmathsetmacro{\wy}{-\wy}
      \fi
      \pgfmathsetmacro{\roff}{0.32/\figscale}
      \node at (\Ox+\roff*\wx, \Oy+\roff*\wy) {$O$};
    \fi
  \fi
  % 中点四边形（虚线，顺次连接 E-F-G-H，恒为平行四边形）
  \ifnum\showmidseg>0
    \draw[dashed] (E) -- (F) -- (G) -- (H) -- cycle;
  \fi
  % 中点处画实心小圆点（绝对半径 1.6pt，不随坐标缩放，明确标出边上有个点）
  \ifnum\showe>0
    \fill (E) circle [radius=1.6pt];
  \fi
  \ifnum\showf>0
    \fill (F) circle [radius=1.6pt];
  \fi
  \ifnum\showg>0
    \fill (G) circle [radius=1.6pt];
  \fi
  \ifnum\showh>0
    \fill (H) circle [radius=1.6pt];
  \fi
  % 顶点标签（顶点逆时针，标签放外侧）
  \node[below left=3pt] at (A) {$A$};
  \node[below=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above=3pt] at (D) {$D$};
  % 中点标签：根据对应 bool 显示
  \ifnum\showe>0
    \node[below=3pt] at (E) {$E$};
  \fi
  \ifnum\showf>0
    \node[right=3pt] at (F) {$F$};
  \fi
  \ifnum\showg>0
    \node[above=3pt] at (G) {$G$};
  \fi
  \ifnum\showh>0
    \node[left=3pt] at (H) {$H$};
  \fi
\end{tikzpicture}
